class Solution {
public:
    int minKBitFlips(vector<int>& nums, int k) {
        int n = nums.size();
        int active = 0;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (i >= k && nums[i - k] >= 2) {
                active--;
                nums[i - k] -= 2;
            }
            if ((nums[i] + active) % 2 == 0) {
                if (i + k > n) return -1;
                active++;
                nums[i] += 2;
                ans++;
            }
        }
        return ans;
    }
};
